-- Shop: synthetic sample data for the dhimantAI "Ask your data" lab.
-- Generated by scripts/datalab/generate_seeds.py. Do not edit by hand.
-- Every name and number is invented. No real person, shop, school or clinic.

CREATE TABLE branches (
  branch_id integer PRIMARY KEY,
  branch_name text NOT NULL,
  city text NOT NULL,
  state text NOT NULL,
  opened_on date NOT NULL,
  floor_area_sqft integer NOT NULL
);
COMMENT ON TABLE branches IS 'One row per branch.';
COMMENT ON COLUMN branches.branch_id IS 'Branch number.';
COMMENT ON COLUMN branches.branch_name IS 'Short name used in the shop.';
COMMENT ON COLUMN branches.city IS 'City.';
COMMENT ON COLUMN branches.state IS 'State.';
COMMENT ON COLUMN branches.opened_on IS 'Date the branch opened. Hubballi opened in the middle of the period.';
COMMENT ON COLUMN branches.floor_area_sqft IS 'Selling area in square feet.';

CREATE TABLE products (
  product_id integer PRIMARY KEY,
  product_name text NOT NULL,
  category text NOT NULL,
  current_price numeric(10,2) NOT NULL
);
COMMENT ON TABLE products IS 'One row per product sold by the chain.';
COMMENT ON COLUMN products.product_id IS 'Product number.';
COMMENT ON COLUMN products.product_name IS 'Product and pack size.';
COMMENT ON COLUMN products.category IS 'Product group.';
COMMENT ON COLUMN products.current_price IS 'Today''s shelf price in rupees. Prices changed during the period; the price actually charged is in sales.unit_price.';

CREATE TABLE sales (
  sale_id integer PRIMARY KEY,
  sale_date date NOT NULL,
  branch_id integer NOT NULL REFERENCES branches,
  product_id integer NOT NULL REFERENCES products,
  quantity integer NOT NULL,
  unit_price numeric(10,2) NOT NULL,
  amount numeric(12,2) NOT NULL
);
COMMENT ON TABLE sales IS 'One row per product, branch and day: the quantity sold that day.';
COMMENT ON COLUMN sales.sale_id IS 'Row number.';
COMMENT ON COLUMN sales.sale_date IS 'Day of the sales.';
COMMENT ON COLUMN sales.branch_id IS 'Branch (see branches).';
COMMENT ON COLUMN sales.product_id IS 'Product (see products).';
COMMENT ON COLUMN sales.quantity IS 'Units sold that day.';
COMMENT ON COLUMN sales.unit_price IS 'Price charged per unit that day, in rupees.';
COMMENT ON COLUMN sales.amount IS 'quantity times unit_price, in rupees, before any returns.';

CREATE TABLE returns (
  return_id integer PRIMARY KEY,
  return_date date NOT NULL,
  sale_id integer NOT NULL REFERENCES sales,
  branch_id integer NOT NULL REFERENCES branches,
  product_id integer NOT NULL REFERENCES products,
  quantity integer NOT NULL,
  refund_amount numeric(12,2) NOT NULL,
  reason text
);
COMMENT ON TABLE returns IS 'Goods brought back by customers. Not subtracted in sales: net sales = sales.amount minus returns.refund_amount.';
COMMENT ON COLUMN returns.return_id IS 'Row number.';
COMMENT ON COLUMN returns.return_date IS 'Day the goods came back.';
COMMENT ON COLUMN returns.sale_id IS 'The sales row they were sold on.';
COMMENT ON COLUMN returns.branch_id IS 'Branch that took the return.';
COMMENT ON COLUMN returns.product_id IS 'Product returned.';
COMMENT ON COLUMN returns.quantity IS 'Units returned.';
COMMENT ON COLUMN returns.refund_amount IS 'Money given back, in rupees.';
COMMENT ON COLUMN returns.reason IS 'Reason noted by the cashier. Often blank: cashiers did not always ask.';
